import math
import torch
import torch.nn as nn
import torch.nn.init as init

from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

# ---------------------------------------------------------------------------
# Hand written PTX implementing a transposed 3D convolution.
#
# Structural optimization applied: CTA-level output tiling along the Wout
# dimension combined with cooperative shared-memory staging of the input
# row.  Each CTA is responsible for a fixed (n, oc, od, oh) output slice and
# a contiguous tile of `blockDim.x` output-width positions.  For every
# (ic, kd, kh) combination visited during accumulation, the entire input row
# X[n, ic, id, ih, :] (length Win) is cooperatively loaded into shared
# memory once per CTA and then reused by every thread in the block while it
# iterates over the kw dimension, instead of every thread independently
// issuing redundant global loads for overlapping input windows.
# ---------------------------------------------------------------------------
PTX_SOURCE = r"""
.version 8.7
.target sm_89
.address_size 64

.extern .shared .align 4 .b8 smem_buf[];

.visible .entry conv_transpose3d_kernel(
    .param .u64 X_ptr,
    .param .u64 W_ptr,
    .param .u64 B_ptr,
    .param .u64 Y_ptr,
    .param .u32 N,
    .param .u32 Cin,
    .param .u32 D,
    .param .u32 H,
    .param .u32 Win,
    .param .u32 Cout,
    .param .u32 Dout,
    .param .u32 Hout,
    .param .u32 Wout,
    .param .u32 kD,
    .param .u32 kH,
    .param .u32 kW,
    .param .u32 strideD,
    .param .u32 strideH,
    .param .u32 strideW,
    .param .u32 padD,
    .param .u32 padH,
    .param .u32 padW,
    .param .u32 dilD,
    .param .u32 dilH,
    .param .u32 dilW,
    .param .u32 groups,
    .param .u32 has_bias
)
{
    .reg .pred   %p<30>;
    .reg .b32    %r<160>;
    .reg .b64    %rd<160>;
    .reg .f32    %f<20>;

    ld.param.u64 %rd1, [X_ptr];
    ld.param.u64 %rd2, [W_ptr];
    ld.param.u64 %rd3, [B_ptr];
    ld.param.u64 %rd4, [Y_ptr];
    ld.param.u32 %r1,  [N];
    ld.param.u32 %r2,  [Cin];
    ld.param.u32 %r3,  [D];
    ld.param.u32 %r4,  [H];
    ld.param.u32 %r5,  [Win];
    ld.param.u32 %r6,  [Cout];
    ld.param.u32 %r7,  [Dout];
    ld.param.u32 %r8,  [Hout];
    ld.param.u32 %r9,  [Wout];
    ld.param.u32 %r10, [kD];
    ld.param.u32 %r11, [kH];
    ld.param.u32 %r12, [kW];
    ld.param.u32 %r13, [strideD];
    ld.param.u32 %r14, [strideH];
    ld.param.u32 %r15, [strideW];
    ld.param.u32 %r16, [padD];
    ld.param.u32 %r17, [padH];
    ld.param.u32 %r18, [padW];
    ld.param.u32 %r19, [dilD];
    ld.param.u32 %r20, [dilH];
    ld.param.u32 %r21, [dilW];
    ld.param.u32 %r22, [groups];
    ld.param.u32 %r23, [has_bias];

    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd4, %rd4;

    mov.u32 %r30, %ntid.x;         // BLOCK_W
    add.s32 %r31, %r9, %r30;
    sub.s32 %r31, %r31, 1;
    div.s32 %r32, %r31, %r30;      // nWTiles = ceil(Wout / BLOCK_W)

    mul.lo.s32 %r33, %r6, %r7;
    mul.lo.s32 %r33, %r33, %r8;
    mul.lo.s32 %r33, %r33, %r32;
    mul.lo.s32 %r34, %r33, %r1;    // total_tiles

    mov.u32 %r35, %ctaid.x;
    mov.u32 %r36, %nctaid.x;
    mov.u32 %r37, %tid.x;

TILE_LOOP:
    setp.ge.s32 %p1, %r35, %r34;
    @%p1 bra TILE_LOOP_END;

    div.s32 %r40, %r35, %r32;
    rem.s32 %r41, %r35, %r32;      // wtile
    div.s32 %r42, %r40, %r8;
    rem.s32 %r43, %r40, %r8;       // oh
    div.s32 %r44, %r42, %r7;
    rem.s32 %r45, %r42, %r7;       // od
    div.s32 %r46, %r44, %r6;       // n
    rem.s32 %r47, %r44, %r6;       // oc

    mul.lo.s32 %r48, %r41, %r30;
    add.s32 %r49, %r48, %r37;      // ow
    setp.lt.s32 %p2, %r49, %r9;    // valid_ow

    div.s32 %r50, %r6, %r22;       // Cout_per_group
    div.s32 %r51, %r2, %r22;       // Cin_per_group
    div.s32 %r52, %r47, %r50;      // g
    rem.s32 %r53, %r47, %r50;      // oc_local
    mul.lo.s32 %r54, %r52, %r51;   // ic_base

    mov.f32 %f1, 0f00000000;
    setp.eq.s32 %p3, %r23, 0;
    @%p3 bra SKIP_BIAS;
    cvta.to.global.u64 %rd10, %rd3;
    mul.wide.s32 %rd11, %r47, 4;
    add.s64 %rd12, %rd10, %rd11;
    ld.global.f32 %f1, [%rd12];
SKIP_BIAS:

    mov.u64 %rd20, smem_buf;

    mov.s32 %r60, 0;
IC_LOOP:
    setp.ge.s32 %p4, %r60, %r51;
    @%p4 bra IC_END;
    add.s32 %r61, %r54, %r60;      // ic

    mov.s32 %r70, 0;
KD_LOOP:
    setp.ge.s32 %p5, %r70, %r10;
    @%p5 bra KD_END;

    mul.lo.s32 %r71, %r70, %r19;
    add.s32 %r72, %r45, %r16;
    sub.s32 %r73, %r72, %r71;
    rem.s32 %r74, %r73, %r13;
    setp.ne.s32 %p6, %r74, 0;
    @%p6 bra KD_CONT;
    div.s32 %r75, %r73, %r13;      // id
    setp.lt.s32 %p7, %r75, 0;
    setp.ge.s32 %p8, %r75, %r3;
    or.pred %p9, %p7, %p8;
    @%p9 bra KD_CONT;

    mov.s32 %r80, 0;
KH_LOOP:
    setp.ge.s32 %p10, %r80, %r11;
    @%p10 bra KH_END;

    mul.lo.s32 %r81, %r80, %r20;
    add.s32 %r82, %r43, %r17;
    sub.s32 %r83, %r82, %r81;
    rem.s32 %r84, %r83, %r14;
    setp.ne.s32 %p11, %r84, 0;
    @%p11 bra KH_CONT;
    div.s32 %r85, %r83, %r14;      // ih
    setp.lt.s32 %p12, %r85, 0;
    setp.ge.s32 %p13, %r85, %r4;
    or.pred %p14, %p12, %p13;
    @%p14 bra KH_CONT;

    // row base index (elements): (((n*Cin+ic)*D+id)*H+ih)
    cvt.s64.s32 %rd30, %r46;
    cvt.s64.s32 %rd31, %r2;
    mul.lo.s64 %rd32, %rd30, %rd31;
    cvt.s64.s32 %rd33, %r61;
    add.s64 %rd34, %rd32, %rd33;
    cvt.s64.s32 %rd35, %r3;
    mul.lo.s64 %rd36, %rd34, %rd35;
    cvt.s64.s32 %rd37, %r75;
    add.s64 %rd38, %rd36, %rd37;
    cvt.s64.s32 %rd39, %r4;
    mul.lo.s64 %rd40, %rd38, %rd39;
    cvt.s64.s32 %rd41, %r85;
    add.s64 %rd42, %rd40, %rd41;   // row_idx
    cvt.s64.s32 %rd43, %r5;
    mul.lo.s64 %rd44, %rd42, %rd43; // row_idx * Win
    mul.lo.s64 %rd45, %rd44, 4;
    add.s64 %rd46, %rd1, %rd45;    // row_base_ptr

    // cooperative load of X[n,ic,id,ih,:] into shared memory
    mov.s32 %r90, %r37;
LOAD_LOOP:
    setp.ge.s32 %p15, %r90, %r5;
    @%p15 bra LOAD_END;
    mul.wide.s32 %rd47, %r90, 4;
    add.s64 %rd48, %rd46, %rd47;
    ld.global.f32 %f5, [%rd48];
    add.s64 %rd50, %rd20, %rd47;
    st.shared.f32 [%rd50], %f5;
    add.s32 %r90, %r90, %r30;
    bra.uni LOAD_LOOP;
LOAD_END:

    bar.sync 0;

    mov.s32 %r100, 0;
KW_LOOP:
    setp.ge.s32 %p16, %r100, %r12;
    @%p16 bra KW_END;

    mul.lo.s32 %r101, %r100, %r21;
    add.s32 %r102, %r49, %r18;
    sub.s32 %r103, %r102, %r101;
    rem.s32 %r104, %r103, %r15;
    setp.ne.s32 %p17, %r104, 0;
    div.s32 %r105, %r103, %r15;
    setp.lt.s32 %p18, %r105, 0;
    setp.ge.s32 %p19, %r105, %r5;
    or.pred %p20, %p18, %p19;
    or.pred %p21, %p17, %p20;
    not.pred %p22, %p21;
    and.pred %p23, %p22, %p2;

    @!%p23 bra KW_CONT;

    mul.wide.s32 %rd60, %r105, 4;
    add.s64 %rd61, %rd20, %rd60;
    ld.shared.f32 %f10, [%rd61];

    cvt.s64.s32 %rd62, %r61;
    cvt.s64.s32 %rd63, %r50;
    mul.lo.s64 %rd64, %rd62, %rd63;
    cvt.s64.s32 %rd65, %r53;
    add.s64 %rd66, %rd64, %rd65;
    cvt.s64.s32 %rd67, %r10;
    mul.lo.s64 %rd68, %rd66, %rd67;
    cvt.s64.s32 %rd69, %r70;
    add.s64 %rd70, %rd68, %rd69;
    cvt.s64.s32 %rd71, %r11;
    mul.lo.s64 %rd72, %rd70, %rd71;
    cvt.s64.s32 %rd73, %r80;
    add.s64 %rd74, %rd72, %rd73;
    cvt.s64.s32 %rd75, %r12;
    mul.lo.s64 %rd76, %rd74, %rd75;
    cvt.s64.s32 %rd77, %r100;
    add.s64 %rd78, %rd76, %rd77;
    mul.lo.s64 %rd79, %rd78, 4;
    add.s64 %rd80, %rd2, %rd79;
    ld.global.f32 %f11, [%rd80];

    fma.rn.f32 %f1, %f10, %f11, %f1;

KW_CONT:
    add.s32 %r100, %r100, 1;
    bra.uni KW_LOOP;
KW_END:

    bar.sync 0;

KH_CONT:
    add.s32 %r80, %r80, 1;
    bra.uni KH_LOOP;
KH_END:

KD_CONT:
    add.s32 %r70, %r70, 1;
    bra.uni KD_LOOP;
KD_END:

    add.s32 %r60, %r60, 1;
    bra.uni IC_LOOP;
IC_END:

    @!%p2 bra STORE_SKIP;
    cvt.s64.s32 %rd90, %r46;
    cvt.s64.s32 %rd91, %r6;
    mul.lo.s64 %rd92, %rd90, %rd91;
    cvt.s64.s32 %rd93, %r47;
    add.s64 %rd94, %rd92, %rd93;
    cvt.s64.s32 %rd95, %r7;
    mul.lo.s64 %rd96, %rd94, %rd95;
    cvt.s64.s32 %rd97, %r45;
    add.s64 %rd98, %rd96, %rd97;
    cvt.s64.s32 %rd99, %r8;
    mul.lo.s64 %rd100, %rd98, %rd99;
    cvt.s64.s32 %rd101, %r43;
    add.s64 %rd102, %rd100, %rd101;
    cvt.s64.s32 %rd103, %r9;
    mul.lo.s64 %rd104, %rd102, %rd103;
    cvt.s64.s32 %rd105, %r49;
    add.s64 %rd106, %rd104, %rd105;
    mul.lo.s64 %rd107, %rd106, 4;
    add.s64 %rd108, %rd4, %rd107;
    st.global.f32 [%rd108], %f1;
STORE_SKIP:

    add.s32 %r35, %r35, %r36;
    bra.uni TILE_LOOP;

TILE_LOOP_END:
    ret;
}
"""

_ENTRY_NAME = "conv_transpose3d_kernel"
_module_cache = None

_BLOCK_W = 128


def _get_module():
    global _module_cache
    if _module_cache is None:
        _module_cache = PtxModule(PTX_SOURCE)
    return _module_cache


def validate_generated_code():
    """Sanity check that the PTX module contains the expected entry point."""
    module = _get_module()
    fn = module.function(_ENTRY_NAME)
    assert fn is not None, f"entry '{_ENTRY_NAME}' not found in PTX module"
    return True


class ModelNew(nn.Module):
    """
    Transposed 3D convolution with a cubic kernel, implemented via a
    hand-written PTX kernel launched through `cutegen.ptx_runtime.PtxModule`.

    The kernel uses CTA-level output tiling over the Wout dimension: each
    CTA owns a fixed (n, oc, od, oh) slice plus a contiguous tile of output
    width positions, and cooperatively stages the reused input row into
    shared memory for the whole CTA before the width-tile threads consume it
    during the kw accumulation loop.
    """

    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, output_padding: int = 0,
                 dilation: int = 1, groups: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.dilation = dilation
        self.groups = groups

        assert in_channels % groups == 0
        assert out_channels % groups == 0

        self.weight = nn.Parameter(
            torch.empty(in_channels, out_channels // groups,
                        kernel_size, kernel_size, kernel_size)
        )
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._module = None

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in, _ = init._calculate_fan_in_and_fan_out(self.weight)
            if fan_in != 0:
                bound = 1.0 / math.sqrt(fan_in)
                init.uniform_(self.bias, -bound, bound)

    def _ensure_module(self):
        if self._module is None:
            self._module = _get_module()
        return self._module

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "input must be a CUDA tensor"
        assert x.dtype == torch.float32, "only float32 supported"

        x_c = x.contiguous()
        w_c = self.weight.contiguous()

        N, Cin, D, H, Win = x_c.shape
        Cout_per_group = w_c.shape[1]
        kD = kH = kW = self.kernel_size
        groups = self.groups
        Cout = self.out_channels

        stride = self.stride
        padding = self.padding
        output_padding = self.output_padding
        dilation = self.dilation

        Dout = (D - 1) * stride - 2 * padding + dilation * (kD - 1) + output_padding + 1
        Hout = (H - 1) * stride - 2 * padding + dilation * (kH - 1) + output_padding + 1
        Wout = (Win - 1) * stride - 2 * padding + dilation * (kW - 1) + output_padding + 1

        assert Dout > 0 and Hout > 0 and Wout > 0, "invalid output size"

        y = torch.empty((N, Cout, Dout, Hout, Wout), device=x.device, dtype=x.dtype)

        has_bias = 1 if self.bias is not None else 0
        if self.bias is not None:
            b_c = self.bias.contiguous()
            bias_ptr = b_c.data_ptr()
        else:
            b_c = None
            bias_ptr = 0

        threads = _BLOCK_W
        n_w_tiles = (Wout + threads - 1) // threads
        total_tiles = N * Cout * Dout * Hout * n_w_tiles
        blocks = max(1, min(total_tiles, 65535))

        # dynamic shared memory holds one input row of length Win (float32)
        shared_mem_bytes = Win * 4

        module = self._ensure_module()
        stream = torch.cuda.current_stream().cuda_stream

        module.launch(
            _ENTRY_NAME,
            grid=(blocks, 1, 1),
            block=(threads, 1, 1),
            shared_mem_bytes=shared_mem_bytes,
            stream=stream,
            args=[
                u64(x_c.data_ptr()),
                u64(w_c.data_ptr()),
                u64(bias_ptr),
                u64(y.data_ptr()),
                i32(N), i32(Cin), i32(D), i32(H), i32(Win),
                i32(Cout), i32(Dout), i32(Hout), i32(Wout),
                i32(kD), i32(kH), i32(kW),
                i32(stride), i32(stride), i32(stride),
                i32(padding), i32(padding), i32(padding),
                i32(dilation), i32(dilation), i32(dilation),
                i32(groups), i32(has_bias),
            ],
        )

        return y

