import math
import torch
import torch.nn as nn
import torch.nn.init as init

from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

# ---------------------------------------------------------------------------
# Hand written PTX implementing a transposed 3D convolution.
#
# One CUDA thread computes one output element Y[n, oc, od, oh, ow].  The
# linear thread index over the (N, Cout, Dout, Hout, Wout) space is used
# directly both to decode (n, oc, od, oh, ow) and as the store offset into Y
# (since Y is contiguous in that exact order).  A grid-stride loop is used so
# that the launch is correct regardless of how many blocks/threads are
# requested.
# ---------------------------------------------------------------------------
PTX_SOURCE = r"""
.version 8.7
.target sm_89
.address_size 64

.visible .entry conv_transpose3d_kernel(
    .param .u64 X_ptr,
    .param .u64 W_ptr,
    .param .u64 B_ptr,
    .param .u64 Y_ptr,
    .param .u32 N,
    .param .u32 Cin,
    .param .u32 D,
    .param .u32 H,
    .param .u32 Win,
    .param .u32 Cout,
    .param .u32 Dout,
    .param .u32 Hout,
    .param .u32 Wout,
    .param .u32 kD,
    .param .u32 kH,
    .param .u32 kW,
    .param .u32 strideD,
    .param .u32 strideH,
    .param .u32 strideW,
    .param .u32 padD,
    .param .u32 padH,
    .param .u32 padW,
    .param .u32 dilD,
    .param .u32 dilH,
    .param .u32 dilW,
    .param .u32 groups,
    .param .u32 has_bias
)
{
    .reg .pred   %p<40>;
    .reg .b32    %r<160>;
    .reg .b64    %rd<130>;
    .reg .f32    %f<20>;

    ld.param.u64 %rd1, [X_ptr];
    ld.param.u64 %rd2, [W_ptr];
    ld.param.u64 %rd3, [B_ptr];
    ld.param.u64 %rd4, [Y_ptr];
    ld.param.u32 %r1,  [N];
    ld.param.u32 %r2,  [Cin];
    ld.param.u32 %r3,  [D];
    ld.param.u32 %r4,  [H];
    ld.param.u32 %r5,  [Win];
    ld.param.u32 %r6,  [Cout];
    ld.param.u32 %r7,  [Dout];
    ld.param.u32 %r8,  [Hout];
    ld.param.u32 %r9,  [Wout];
    ld.param.u32 %r10, [kD];
    ld.param.u32 %r11, [kH];
    ld.param.u32 %r12, [kW];
    ld.param.u32 %r13, [strideD];
    ld.param.u32 %r14, [strideH];
    ld.param.u32 %r15, [strideW];
    ld.param.u32 %r16, [padD];
    ld.param.u32 %r17, [padH];
    ld.param.u32 %r18, [padW];
    ld.param.u32 %r19, [dilD];
    ld.param.u32 %r20, [dilH];
    ld.param.u32 %r21, [dilW];
    ld.param.u32 %r22, [groups];
    ld.param.u32 %r23, [has_bias];

    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd4, %rd4;

    // total = N * Cout * Dout * Hout * Wout
    mul.lo.s32 %r30, %r6, %r7;
    mul.lo.s32 %r30, %r30, %r8;
    mul.lo.s32 %r30, %r30, %r9;
    mul.lo.s32 %r31, %r30, %r1;

    mov.u32 %r40, %ctaid.x;
    mov.u32 %r41, %ntid.x;
    mov.u32 %r42, %tid.x;
    mad.lo.s32 %r43, %r40, %r41, %r42;
    mov.u32 %r44, %nctaid.x;
    mul.lo.s32 %r45, %r44, %r41;

LOOP_START:
    setp.ge.s32 %p1, %r43, %r31;
    @%p1 bra LOOP_END;

    // decode idx -> n, oc, od, oh, ow
    div.s32 %r51, %r43, %r9;
    rem.s32 %r52, %r43, %r9;      // ow
    div.s32 %r53, %r51, %r8;
    rem.s32 %r54, %r51, %r8;      // oh
    div.s32 %r55, %r53, %r7;
    rem.s32 %r56, %r53, %r7;      // od
    div.s32 %r57, %r55, %r6;      // n
    rem.s32 %r58, %r55, %r6;      // oc

    div.s32 %r60, %r6, %r22;      // Cout_per_group
    div.s32 %r61, %r2, %r22;      // Cin_per_group
    div.s32 %r62, %r58, %r60;     // g
    rem.s32 %r63, %r58, %r60;     // oc_local
    mul.lo.s32 %r64, %r62, %r61;  // ic_base

    mov.f32 %f1, 0f00000000;
    setp.eq.s32 %p2, %r23, 0;
    @%p2 bra SKIP_BIAS;
    cvta.to.global.u64 %rd10, %rd3;
    mul.wide.s32 %rd11, %r58, 4;
    add.s64 %rd12, %rd10, %rd11;
    ld.global.f32 %f1, [%rd12];
SKIP_BIAS:

    mov.s32 %r70, 0;
IC_LOOP:
    setp.ge.s32 %p3, %r70, %r61;
    @%p3 bra IC_END;
    add.s32 %r71, %r64, %r70;

    mov.s32 %r80, 0;
KD_LOOP:
    setp.ge.s32 %p4, %r80, %r10;
    @%p4 bra KD_END;

