class ModelNew(nn.Module):
    """
    Transposed 3D convolution with a cubic kernel, implemented via a
    hand-written PTX kernel launched through `cutegen.ptx_runtime.PtxModule`.

    The kernel uses CTA-level output tiling over the Wout dimension: each
    CTA owns a fixed (n, oc, od, oh) slice plus a contiguous tile of output
    width positions, and cooperatively stages the reused input row into
    shared memory for the whole CTA before the width-tile threads consume it
    during the kw accumulation loop.
    """

    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, output_padding: int = 0,
                 dilation: int = 1, groups: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.dilation = dilation
        self.groups = groups

        assert in_channels % groups == 0
        assert out_channels % groups == 0

        self.weight = nn.Parameter(
            torch.empty(in_channels, out_channels // groups,
                        kernel_size, kernel_size, kernel_size)
        )
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._module = None

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in, _ = init._calculate_fan_in_and_fan_out(self.weight)
            if fan_in != 0:
                bound = 1.0 / math.sqrt(fan_in)
                init.uniform_(self.bias, -bound, bound)

    def _ensure_module(self):
        if self._module is None:
            self._module = _get_module()
        return self._module

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "input must be a CUDA tensor"
        assert x.dtype == torch.float32, "only float32 supported"

        x_c = x.contiguous()
        w_c = self.weight.contiguous()

        N, Cin, D, H, Win = x_c.shape
        Cout_per_group = w_c.shape[1]
        kD = kH = kW = self.kernel_size
        groups = self.groups
        Cout = self.out_channels

        stride = self.stride
        padding = self.padding
        output_padding = self.output_padding
        dilation = self.dilation

        Dout = (D - 1) * stride - 2 * padding + dilation * (kD - 1) + output_padding + 1
        Hout = (H - 1) * stride - 2 * padding + dilation * (kH - 1) + output_padding + 1
        Wout = (Win - 1) * stride - 2 * padding + dilation * (kW - 1) + output_padding + 1

        assert Dout > 0 and Hout > 0 and Wout > 0, "invalid output size"

        y = torch.empty((N, Cout, Dout, Hout, Wout), device=x.device, dtype=x.dtype)

        has_bias = 1 if self.bias is not None else 0
        if self.bias is not None:
            b_c = self.bias.contiguous()
            bias_ptr = b_c.data_ptr()
        else:
            b_c = None
            bias_ptr = 0

        threads = _BLOCK_W
        n_w_tiles = (Wout + threads - 1) // threads
        total_tiles = N * Cout * Dout * Hout * n_w_tiles
        blocks = max(1, min(total_tiles, 65535))

        # static shared memory (matches .shared array size in PTX) holds one
        # input row of length Win (float32); this runtime's launch() has no
        # dynamic shared-memory sizing hook, so the buffer is statically
        # sized in PTX instead.
        _STATIC_SMEM_BYTES = 4096
        assert Win * 4 <= _STATIC_SMEM_BYTES, "Win too large for static shared memory buffer"

        module = self._ensure_module()
        stream = torch.cuda.current_stream().cuda_stream

        module.launch(
            _ENTRY_NAME,
            grid=(blocks, 1, 1),
            block=(threads, 1, 1),
            shared_mem=shared_mem_bytes,
            stream=stream,
            args=[
                u64(x_c.data_ptr()),
                u64(bias_ptr),
                u64(y.data_ptr()),
                i32(N), i32(Cin), i32(D), i32(H), i32(Win),
                i32(Cout), i32(Dout), i32(Hout), i32(Wout),
                i32(kD), i32(kH), i32(kW),
                i32(stride), i32(stride), i32(stride),
                i32(padding), i32(padding), i32(padding),
                i32(dilation), i32(dilation), i32(dilation),
                i32(groups), i32(has_bias),
            ],
        )

        return y

